+# AI 代码审查自动化系统 - 核心实现
import ast
import re
from typing import List, Dict
from dataclasses import dataclass
from enum import Enum

class Severity(Enum):
    INFO = "info"
    WARNING = "warning"
    ERROR = "error"
    CRITICAL = "critical"

class IssueType(Enum):
    CODE_SMELL = "code_smell"
    SECURITY = "security"
    BUG = "bug"

@dataclass
class ReviewIssue:
    file: str
    line: int
    message: str
    severity: Severity
    issue_type: IssueType
    suggestion: str = None

class SecurityScanner:
    """安全检测器"""
    def __init__(self):
        self.patterns = {
            'sql_injection': (r'(execute|query)\s*\(.*%s', 'Use parameterized queries', Severity.CRITICAL),
            'hardcoded_secret': (r'(password|api_key)\s*=\s*["\'][^"\']{8,}', 'Use environment variables', Severity.CRITICAL),
            'eval_usage': (r'\beval\s*\(|\bexec\s*\(', 'Avoid eval/exec', Severity.ERROR)
        }

    def scan(self, code: str, file_path: str) -> List[ReviewIssue]:
        issues = []
        for line_num, line in enumerate(code.split('\n'), 1):
            for issue_type, (pattern, suggestion, severity) in self.patterns.items():
                if re.search(pattern, line):
                    issues.append(ReviewIssue(file_path, line_num, f"{issue_type} detected", severity, IssueType.SECURITY, suggestion))
        return issues

class CodeSmellDetector:
    """代码异味检测"""
    def __init__(self):
        self.max_function_length = 50
        self.max_parameters = 5

    def detect(self, tree: ast.AST, file_path: str) -> List[ReviewIssue]:
        issues = []
        for node in ast.walk(tree):
            if isinstance(node, ast.FunctionDef):
                line_count = getattr(node, 'end_lineno', node.lineno + 10) - node.lineno
                if line_count > self.max_function_length:
                    issues.append(ReviewIssue(file_path, node.lineno, f"Function too long ({line_count} lines)", Severity.WARNING, IssueType.CODE_SMELL, "Break into smaller functions"))
                if len(node.args.args) > self.max_parameters:
                    issues.append(ReviewIssue(file_path, node.lineno, f"Too many parameters ({len(node.args.args)})", Severity.WARNING, IssueType.CODE_SMELL, "Use config object"))
        return issues

class CodeReviewer:
    """代码审查器"""
    def __init__(self):
        self.security_scanner = SecurityScanner()
        self.code_smell_detector = CodeSmellDetector()

    def review_file(self, file_path: str, code: str) -> List[ReviewIssue]:
        issues = self.security_scanner.scan(code, file_path)
        try:
            tree = ast.parse(code)
            issues.extend(self.code_smell_detector.detect(tree, file_path))
        except SyntaxError as e:
            issues.append(ReviewIssue(file_path, e.lineno or 0, f"Syntax error", Severity.ERROR, IssueType.BUG))
        return issues
